extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var basket := await instantiate_scene("res://basket.tscn")
	if not check("basket", basket != null, "La scena basket.tscn deve istanziarsi senza errori"):
		return
	check("has_func", has_function(basket, "get_catch_point"), "basket.gd deve dichiarare la funzione get_catch_point()")
	var catch_pt = call_if_exists(basket, "get_catch_point")
	check("catch_val", catch_pt is Vector2 and catch_pt == basket.global_position, "get_catch_point deve restituire esattamente global_position")
	basket.position = Vector2(400, 300)
	var updated_pt = call_if_exists(basket, "get_catch_point")
	check("updated_val", updated_pt == Vector2(400, 300), "get_catch_point deve aggiornarsi quando il nodo si muove")

